// Hand-written test helper, not generated by mockery — kept alongside the
// generated mocks because it builds directly on TransactionManager/Tx.
// `make mocks` does not overwrite it.

package mocks

import (
	"context"

	"smart-grid-asset-registry/domain/repository"

	"github.com/stretchr/testify/mock"
)

// StubWithinTx makes txManager.WithinTx run fn against trx with the same
// commit/rollback-on-error semantics gormtx implements in production, so
// trx.EXPECT().Commit()/Rollback() set by the caller assert the right thing.
func StubWithinTx(txManager *TransactionManager, trx *Tx) {
	txManager.EXPECT().
		WithinTx(mock.Anything, mock.Anything).
		RunAndReturn(func(ctx context.Context, fn func(context.Context, repository.Tx) error) error {
			if err := fn(ctx, trx); err != nil {
				_ = trx.Rollback()
				return err
			}
			return trx.Commit()
		})
}

// NewMockTxManager returns a TransactionManager mock wired via StubWithinTx;
// set Commit/Rollback expectations on the returned Tx per test case.
func NewMockTxManager(t interface {
	mock.TestingT
	Cleanup(func())
}) (*TransactionManager, *Tx) {
	txManager := NewTransactionManager(t)
	trx := NewTx(t)
	StubWithinTx(txManager, trx)
	return txManager, trx
}
